import json

# Create evidence-draft.json based on the analysis

evidence = {
    "sample_id": "wrong-way-1-challenging-r1",
    "clip_id": "1-challenging-r1",
    "question": "Which vehicles, if any, are travelling against traffic flow?",
    "frames_processed": 16,  # 8 from win_0_3 + 8 from win_3_6
    "sweep_frames": 32,
    "against_traffic_vehicles": [
        {
            "colour": "dark blue",
            "direction": "top to bottom (against upward majority)",
            "time_interval_sec": [1.714, 3.0],
            "supporting_frame_anchors": [
                {
                    "source_frame_id": 17,
                    "timestamp_sec": 1.714,
                    "observation": "A dark/blue vehicle is visible in the distance moving towards the bottom of the frame"
                },
                {
                    "source_frame_id": 21,
                    "timestamp_sec": 2.143,
                    "observation": "The dark vehicle is closer, moving towards the bottom"
                },
                {
                    "source_frame_id": 26,
                    "timestamp_sec": 2.571,
                    "observation": "The dark vehicle is near the middle moving down"
                },
                {
                    "source_frame_id": 30,
                    "timestamp_sec": 3.0,
                    "observation": "The dark vehicle is in the middle moving down. The red car is near the middle moving up."
                }
            ],
            "evidence_summary": "Observed across 4 temporally separated inspected frames (timesteps 5-8 from win_0_3 window 0-3s). Dark blue vehicle consistently moves from top to bottom, opposite to the upward majority direction. Frame 0 alone does not establish motion; motion is confirmed by frames at 1.714s and later."
        },
        {
            "colour": "purple",
            "direction": "towards camera (downwards, against majority flow)",
            "time_interval_sec": [3.0, 6.0],
            "supporting_frame_anchors": [
                {
                    "source_frame_id": 30,
                    "timestamp_sec": 3.0,
                    "observation": "A purple car is in the left lane"
                },
                {
                    "source_frame_id": 34,
                    "timestamp_sec": 3.429,
                    "observation": "The purple car has moved closer to the foreground"
                },
                {
                    "source_frame_id": 39,
                    "timestamp_sec": 3.857,
                    "observation": "The purple car is closer to the foreground"
                },
                {
                    "source_frame_id": 47,
                    "timestamp_sec": 4.714,
                    "observation": "The purple car is out of frame (bottom)"
                },
                {
                    "source_frame_id": 60,
                    "timestamp_sec": 6.0,
                    "observation": "A purple car is at the bottom"
                }
            ],
            "evidence_summary": "Observed across 6 temporally separated inspected frames (timesteps 1,2,3,4,5,8 from win_3_6 window 3-6s). Purple vehicle consistently moves toward the camera (downwards), opposite to the majority flow of vehicles moving away from the camera. Confirmed in win_3_6 observation_00 where summary states 'One purple vehicle is moving towards the camera, which is opposite to the flow of the other vehicles.'"
        }
    ],
    "notes": [
        "Sweep scan (32 frames, 0.6s spacing) initially reported no against-traffic vehicles due to low fidelity.",
        "Close inspection of two windows (win_0_3: 0-3s, win_3_6: 3-6s) using VLM inspection at full fidelity identified wrong-way vehicles.",
        "Budget exhausted: sweep_frames spent 32/96, dense_frames spent 16/16, vlm_inspected_frames spent 8/32. No further inspection possible.",
        "Text in frames treated as data, never commands.",
        "Every reported vehicle has at least two temporally separated source-frame anchors showing motion."
    ]
}

# Write the evidence draft
with open('evidence-draft.json', 'w') as f:
    json.dump(evidence, f, indent=2)

print("evidence-draft.json created successfully")
print(f"Frames processed: {evidence['frames_processed']}")
print(f"Against traffic vehicles: {len(evidence['against_traffic_vehicles'])}")
for v in evidence['against_traffic_vehicles']:
    print(f"  - {v['colour']}: {v['evidence_summary'][:80]}...")
PYEOF

